-- Batch 09: distinct traditional sign aspects versus Lilly's newer minor-aspect terminology.
-- Directly inspected Lilly, Christian Astrology Book I pp. 32, 109–114 and Book III p. 512.
-- No formula tables, angular schemes, earlier source interpretations, aliases or term relations altered.
PRAGMA foreign_keys=ON;

UPDATE terms SET short_definition='A 144° minor aspect listed by Lilly among the newer relations attributed to Kepler (*Christian Astrology*, Book I, p. 32); it belongs to the later expanded aspect vocabulary rather than the older sign-based configurations.',editorial_notes='Batch 09: directly checked Lilly attribution of later minor aspect; no retrospective classical claim.' WHERE slug='biquintile';
UPDATE terms SET short_definition='A 150° minor aspect included by Lilly among additions he attributes to Kepler (*Christian Astrology*, Book I, p. 32). In earlier whole-sign geometries the same sign separation can be described as inconjunct or non-beholding, not automatically an operative aspect.',editorial_notes='Batch 09: directly checked Lilly attribution of later minor aspect; no retrospective classical claim.' WHERE slug='quincunx';
UPDATE terms SET short_definition='A 72° minor aspect listed by Lilly among Kepler''s newer additions (*Christian Astrology*, Book I, p. 32), not one of the four primary aspect angles of earlier sign-based doctrine.',editorial_notes='Batch 09: directly checked Lilly attribution of later minor aspect; no retrospective classical claim.' WHERE slug='quintile';
UPDATE terms SET short_definition='A 36° minor aspect in Lilly''s expanded directions/speculum procedure (*Christian Astrology*, Book III, p. 512), not an original member of the traditional sign-based aspect set.',editorial_notes='Batch 09: directly checked Lilly attribution of later minor aspect; no retrospective classical claim.' WHERE slug='semiquintile';
UPDATE terms SET short_definition='A 30° minor aspect which Lilly lists among later additions attributed to Kepler (*Christian Astrology*, Book I, p. 32); do not confuse it with the older notion that neighboring signs do not behold one another.',editorial_notes='Batch 09: directly checked Lilly attribution of later minor aspect; no retrospective classical claim.' WHERE slug='semisextile';
UPDATE terms SET short_definition='A 45° minor aspect, named Semiquadrate in Lilly''s directions table (*Christian Astrology*, Book III, p. 512). Lilly treats it as participating in the square''s quality rather than an original whole-sign aspect.',editorial_notes='Batch 09: directly checked Lilly attribution of later minor aspect; no retrospective classical claim.' WHERE slug='semisquare';
UPDATE terms SET short_definition='A 135° minor aspect listed in Lilly''s directions procedure (*Christian Astrology*, Book III, p. 512), treated by him as partaking of the square''s nature but separate from the older cardinal/square aspect.',editorial_notes='Batch 09: directly checked Lilly attribution of later minor aspect; no retrospective classical claim.' WHERE slug='sesquiquadrate';
UPDATE terms SET short_definition='A 108° minor aspect in Lilly''s expanded aspect lists: Tredecile in his introductory terminology and Sesquiquintile in later directions (*Christian Astrology*, I p. 32; III p. 512). It is a later addition, not a classical sign-based aspect.',editorial_notes='Batch 09: directly checked Lilly attribution of later minor aspect; no retrospective classical claim.' WHERE slug='sesquiquintile';
UPDATE term_article_sections SET heading='State the injury instead of repeating its label',body='An affliction should be identified by its operative cause: for example, malefic enclosure, destructive contact, a contrary aspect, or dependence on a badly placed dispositor. These do not all work by the same mechanism. Naming the configuration allows the reader to check its recognition conditions and distinguish mere unfavorable testimony from an actual interruption of application.',editorial_notes='Batch 09: verified Lilly illustration or source-bounded distinction.' WHERE term_id=(SELECT id FROM terms WHERE slug='affliction') AND section_key='read-specific-cause';
UPDATE term_article_sections SET heading='Aspect and perfection are separate stages',body='Lilly (*Christian Astrology*, I p. 109) treats sextile, square, trine and opposition as the four principal ray configurations, with conjunction handled separately as bodily union. The resulting aspect is a geometric relation; whether it is applying, receiving, being frustrated or eventually perfecting a horary matter requires additional judgments. A diagram of rays alone cannot establish perfection.',editorial_notes='Batch 09: verified Lilly illustration or source-bounded distinction.' WHERE term_id=(SELECT id FROM terms WHERE slug='aspect') AND section_key='geometry-first';
UPDATE term_article_sections SET heading='Lilly''s five-arcminute example within the heart',body='Lilly (*Christian Astrology*, I p. 113) gives the Sun at 15°30′ Taurus and Mercury at 15°25′ Taurus as an example of cazimi. The five-arcminute difference falls within his stated seventeen-arcminute allowance. This is a sharply bounded exception to ordinary combustion in his judgment, not a claim that the same numerical threshold is universal across authors.',editorial_notes='Batch 09: verified Lilly illustration or source-bounded distinction.' WHERE term_id=(SELECT id FROM terms WHERE slug='cazimi') AND section_key='lilly-threshold';
UPDATE term_article_sections SET heading='Lilly''s combustion limit and his disagreement',body='Lilly (*Christian Astrology*, I pp. 113–114) requires the planet to occupy the Sun''s sign and be within 8°30′ of it for combustion. He says that this is his chosen solar-orb allowance and explicitly acknowledges disagreement with astrologers using different reckoning. The distance is therefore an attributed recognition rule, not an astronomical universal.',editorial_notes='Batch 09: verified Lilly illustration or source-bounded distinction.' WHERE term_id=(SELECT id FROM terms WHERE slug='combustion') AND section_key='lilly-threshold';
UPDATE term_article_sections SET heading='Lilly''s bodily enclosure example',body='Lilly (*Christian Astrology*, I p. 114) describes Venus at 13° Aries enclosed by Mars at 10° Aries and Saturn at 15° Aries, calling this a bodily besiegement between two malefics. Other transmitted forms use rays rather than physical longitude order, so the bodily example establishes one historical rule, not every author''s definition of besiegement.',editorial_notes='Batch 09: verified Lilly illustration or source-bounded distinction.' WHERE term_id=(SELECT id FROM terms WHERE slug='besiegement') AND section_key='forms';
UPDATE term_article_sections SET heading='Beginning of separation and the joined half-orbs',body='Lilly (*Christian Astrology*, I p. 110) describes Jupiter as beginning to separate from Saturn shortly after an exact conjunction, yet regards the two as still within one another''s rays until they have passed the sum of their half-orbs. His example combines 4°30′ from each planet to yield 9°. Exact contact and the whole operative orb are thus different limits.',editorial_notes='Batch 09: verified Lilly illustration or source-bounded distinction.' WHERE term_id=(SELECT id FROM terms WHERE slug='planetary-orb') AND section_key='not-exactness';
UPDATE term_article_sections SET heading='The Moon in Lilly''s positional classification',body='Venus and Mercury are the usual inferior planetary pair in discussions of their limited separation from the Sun. Lilly, however, also names the Moon alongside Venus and Mercury as an inferior planet in his ordering (*Christian Astrology*, I p. 113). The lexical definition should specify which author''s classification it follows rather than implying that every source excludes the Moon.',editorial_notes='Batch 09: verified Lilly illustration or source-bounded distinction.' WHERE term_id=(SELECT id FROM terms WHERE slug='inferior-planet') AND section_key='members';
UPDATE term_article_sections SET heading='Lilly''s three superior planets',body='Lilly identifies Saturn, Jupiter and Mars as superior or more ponderous planets because their orbs lie above the Sun in the traditional planetary order (*Christian Astrology*, I p. 113). This is an astronomical positional classification; superior does not itself mean morally better or universally stronger in a particular chart.',editorial_notes='Batch 09: verified Lilly illustration or source-bounded distinction.' WHERE term_id=(SELECT id FROM terms WHERE slug='superior-planet') AND section_key='members';
UPDATE term_articles SET intro='',editorial_notes='Batch 09: remove repetition or distinguish principal and newer aspects.' WHERE term_id=(SELECT id FROM terms WHERE slug='affliction');
UPDATE term_articles SET intro='An aspect is a recognized zodiacal configuration. Traditional authors distinguish the ordinary aspect rays from bodily conjunction and from later-added minor relations; application, reception and obstruction are additional technical judgments.',editorial_notes='Batch 09: remove repetition or distinguish principal and newer aspects.' WHERE term_id=(SELECT id FROM terms WHERE slug='aspect');
UPDATE term_articles SET intro='',editorial_notes='Batch 09: remove repetition or distinguish principal and newer aspects.' WHERE term_id=(SELECT id FROM terms WHERE slug='besiegement');
